// Insert example (p = {x,y})
function insertPoint(p){
  for(let dx=-1; dx<=1; dx++) for(let dy=-1; dy<=1; dy++){
    const cell = grid[coord(p.x+dx,p.y+dy)];
    if(cell) for(let q of cell){ if(dist2(p,q) <= R2) closeCount++; }
  }
  grid[coord(p.x,p.y)].push(p);
}
